"""Customer-facing accessory demo. Inventory provenance stays in the background."""
from pathlib import Path
import html, json, re
from urllib.parse import quote
R=Path(__file__).resolve().parent
def e(value): return html.escape(str(value),quote=True)
def slug(value): return re.sub(r'[^a-z0-9]+','-',value.lower()).strip('-')
def inventory(): return json.loads((R/'inventory.json').read_text())['products']
CATEGORIES={'glass':'Glass & pipes','grinders':'Grinders','papers':'Papers & cones','trays':'Rolling trays','lighters':'Lighters','storage':'Storage','cleaning':'Cleaning & care','scents':'Scents & incense'}
def price(p):
 amounts=[o['amount_minor'] for o in p['options']]
 return ('From ' if min(amounts)!=max(amounts) else '')+f'${min(amounts)/100:,.2f}'
def card(p):
 return f'''<article class="retail-card" data-product-purchase data-retail-item data-id="{e(p['id'])}" data-name="{e(p['name'])}" data-brand="{e(p['brand'])}" data-category="{e(p['category'])}" data-price="{min(o['amount_minor'] for o in p['options'])}" data-search="{e(p['name']+' '+p['brand']+' '+CATEGORIES[p['category']]+' '+p['description'])}"><a class="retail-product-image" href="product-{p['id']}.html" aria-label="View {e(p['name'])}"><img src="{p['image']}" alt="{e(p['name'])}" width="500" height="500" loading="lazy"></a><div class="retail-card-body"><span class="retail-brand">{e(p['brand'])}</span><h2><a href="product-{p['id']}.html">{e(p['name'])}</a></h2><div class="retail-card-bottom"><p class="retail-price" data-product-price="{p['id']}">{price(p)}</p><button class="add-to-cart" type="button" data-cart-add="{p['id']}" aria-label="{'Choose options for' if len(p['options'])>1 else 'Add'} {e(p['name'])}{'' if len(p['options'])>1 else ' to cart'}">{'Choose options' if len(p['options'])>1 else 'Add to cart'}</button></div></div></article>'''
def collection(products,title='Good gear. Local spirit.',intro='Glass, papers, grinders and the little things that make the setup yours.'):
 counts={k:sum(p['category']==k for p in products) for k in CATEGORIES}
 brands=sorted({p['brand'] for p in products},key=str.casefold)
 return f'''<section class="retail-hero"><div><span class="retail-kicker">ASHES SMOKE SHOP / DENTON + LEWISVILLE</span><h1>{e(title)}</h1><p>{e(intro)}</p></div><a class="retail-shop-stamp" href="locations.html"><span aria-hidden="true">✦</span><b>Two local shops.</b><span>Find your Ashes ↗</span></a></section><section class="retail-shop" aria-label="Shop accessories"><div class="retail-toolbar"><label class="retail-search"><span class="visually-hidden">Search products</span><svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true"><circle cx="10" cy="10" r="6" fill="none" stroke="currentColor" stroke-width="2"/><path d="m15 15 6 6" stroke="currentColor" stroke-width="2"/></svg><input type="search" name="q" data-retail-search placeholder="Search glass, RAW, grinders…" autocomplete="off"></label><button class="retail-filter-toggle" type="button" aria-expanded="false" aria-controls="shop-filters">Filters</button><label class="retail-sort"><span>Sort</span><select name="sort" data-retail-sort><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name: A–Z</option></select></label></div><nav class="retail-chips" aria-label="Shop by category"><button type="button" data-retail-category="all" aria-pressed="true">All accessories</button>{''.join(f'<button type="button" data-retail-category="{k}" aria-pressed="false">{v}</button>' for k,v in CATEGORIES.items() if counts[k])}</nav><div class="retail-layout"><aside class="retail-sidebar" id="shop-filters"><div class="retail-filter-heading"><h2>Filters</h2><button type="button" data-retail-reset>Reset</button></div><label>Category<select name="category" data-retail-category-select><option value="all">All accessories</option>{''.join(f'<option value="{k}">{v} ({counts[k]})</option>' for k,v in CATEGORIES.items() if counts[k])}</select></label><label>Brand<select name="brand" data-retail-brand><option value="all">All brands</option>{''.join(f'<option value="{e(b)}">{e(b)}</option>' for b in brands)}</select></label><label>Price<select name="price" data-retail-price><option value="all">Any price</option><option value="under-10">Under $10</option><option value="10-25">$10–$24.99</option><option value="25-50">$25–$49.99</option><option value="over-50">$50 and up</option></select></label><div class="retail-sidebar-note"><b>A proper shop, a practice order.</b><p>Try the cart and checkout with real products from nearby retailers. This assortment is for the demo.</p><a href="catalog-about.html">About this preview ↗</a></div></aside><div class="retail-main"><div class="retail-results"><p data-retail-count role="status">{len(products)} products</p><span>Reference prices · Demo inventory</span></div><div class="retail-grid">{''.join(card(p) for p in products)}</div><div class="retail-empty" hidden><h2>No matches this time.</h2><p>Try another search or clear your filters.</p><button class="button dark" type="button" data-retail-reset>Show all products</button></div></div></div></section>'''
def home_page(icon, store_sections):
 products=inventory()
 tiles=[('glass','Glass & pipes','Water pipes, bubblers & more','pipe'),('grinders','Grinders','Find your daily grind','grinder'),('papers','Papers & cones','Roll your own way','papers'),('trays','Rolling trays','Keep your setup together','tray'),('lighters','Lighters','A little spark','lighter'),('storage','Storage','A place for the essentials','bag'),('cleaning','Cleaning & care','Keep your pieces fresh','cleaner'),('scents','Scents & incense','Set the mood','plant')]
 custom_icons={'tray':'<rect x="5" y="13" width="54" height="38" rx="8"/><rect x="11" y="19" width="42" height="26" rx="5"/>','lighter':'<rect x="20" y="25" width="25" height="33" rx="5"/><path d="M20 25V14h18v11M20 33h25M29 13V7M33 7v6M45 14c9-6 8-10 4-13-1 5-8 7-4 13Z"/>','cleaner':'<path d="M22 22h20v9l7 11v15H15V42l7-11ZM25 22V12h13v10M24 12V5h23v7H24ZM38 12l10 11M15 43h34M24 49h16"/>'}
 def category_icon(kind):
  if kind not in custom_icons:return icon(kind)
  return '<svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+custom_icons[kind]+'</svg>'
 category_cards=''.join(f'<a class="home-shop-category" href="explore.html?category={key}"><span class="home-category-icon">{category_icon(kind)}</span><span><strong>{title}</strong><small>{desc}</small></span><span class="home-category-arrow" aria-hidden="true">↗</span></a>' for key,title,desc,kind in tiles)
 return '''<section class="welcome-hero"><div class="welcome-copy"><span class="welcome-eyebrow">DENTON + OLD TOWN LEWISVILLE</span><h1>A smoke shop <br>with a little <br><em>more soul.</em></h1><p>Glass, papers, grinders and everyday essentials. A little offbeat. Always room to find your thing.</p><div class="welcome-actions"><a class="button dark" href="explore.html">Shop accessories <span aria-hidden="true">→</span></a><a class="button outline" href="locations.html">Locations & hours</a></div><a class="welcome-guide" href="categories.html">See what’s in the shops ↗</a></div><figure class="welcome-art"><img src="assets/ashes-v4-hero.webp" alt="Colorful Ashes illustration of a relaxed skeleton with a grinder, rolling papers and a glass pipe" width="1254" height="1254" fetchpriority="high"></figure></section><section class="home-shop-section" aria-labelledby="home-category-heading"><div class="home-section-heading"><div><h2 id="home-category-heading">Find your thing.</h2><p>Go straight to what you came for.</p></div><a class="text-link" href="explore.html">Shop all accessories →</a></div><div class="home-category-grid">'''+category_cards+'''</div></section><section class="home-featured" aria-labelledby="home-featured-heading"><div class="home-section-heading"><div><h2 id="home-featured-heading">Take a closer look.</h2><p>From the demo assortment · Retailer reference prices</p></div><a class="text-link" href="explore.html">View all '''+str(len(products))+''' products →</a></div><div class="retail-grid">'''+''.join(card(p) for p in products[:4])+'''</div></section><section class="home-visit" id="locations" aria-labelledby="home-visit-heading"><div class="home-section-heading"><div><span class="welcome-eyebrow">INDEPENDENT SPIRIT. NORTH TEXAS ROOTS.</span><h2 id="home-visit-heading">Two shops. Same Ashes.</h2><p>Find the address, hours and directions for your neighborhood shop.</p></div><a class="text-link" href="story.html">Our story →</a></div>'''+store_sections+'''</section><section class="home-help"><div><span aria-hidden="true">✦</span><h2>Need a hand finding your thing?</h2></div><a class="button outline" href="contact.html">Talk to a shop →</a></section>'''
def build_catalog(page,icon):
 products=inventory()
 # Only generated catalog pages are retired; source research and Git history remain.
 for pattern in ('product-*.html','brand-*.html'):
  for old in (R/'docs').glob(pattern): old.unlink()
 body=collection(products)
 for name in ('explore.html','merchandise.html'):
  page(name,'Shop Glass, Papers & Accessories','Explore real smoke-shop accessories in the Ashes storefront demo. Search products, build a cart and try checkout.',body,'products')
 for p in products:
  other=[x for x in products if x['category']==p['category'] and x['id']!=p['id']][:4]
  option_control=f'<div data-product-options="{p["id"]}"></div>' if len(p['options'])>1 else f'<p class="retail-option">{e(p["options"][0]["label"])}</p>'
  source=p['source']
  details=f'''<div class="retail-breadcrumb"><a href="explore.html">Shop</a><span>/</span><a href="explore.html?category={p['category']}">{CATEGORIES[p['category']]}</a></div><section class="retail-detail"><div class="retail-detail-photo"><img data-detail-image="{p['id']}" src="{p['options'][0].get('image',p['image'])}" alt="{e(p['name'])}" width="700" height="700" fetchpriority="high"></div><div class="retail-detail-copy" data-product-purchase><a class="retail-brand" href="explore.html?brand={e(quote(p['brand']))}">{e(p['brand'])}</a><h1>{e(p['name'])}</h1><p class="retail-price" data-product-price="{p['id']}">{price(p)}</p><p class="retail-reference">Retailer reference price · Demo inventory</p><p class="retail-description">{e(p['description'])}</p>{option_control}<button class="add-to-cart" data-cart-add="{p['id']}" type="button">Add to cart</button><p class="retail-detail-note">Try checkout with pickup or shipping. No payment or real order.</p><details class="retail-source-note"><summary>Product details & source</summary><p>This product and its photo are included as a storefront example based on <a href="{e(source['url'])}" target="_blank" rel="noopener">{e(source['retailer'])}’s listing ↗</a>, checked {e(source['checked_at'][:10])}. The price and options shown are that retailer’s published reference, not Ashes’s confirmed stock or pricing.</p><p>{e(p.get('source_note','Online availability can change. The source listing is not proof of a completed purchase.'))}</p></details></div></section>'''
  if other:details+='<section class="retail-related"><h2>Keep building your setup</h2><div class="retail-grid">'+''.join(card(x) for x in other)+'</div></section>'
  page('product-'+p['id']+'.html',p['name'],p['description'],details,'products')
 brands=sorted({p['brand'] for p in products},key=str.casefold)
 brandbody='<section class="retail-hero"><div><span class="retail-kicker">FIND YOUR FAVORITES</span><h1>Shop by brand.</h1><p>Names you know. Accessories worth a closer look.</p></div></section><section class="retail-brands">'+''.join(f'<a href="explore.html?brand={e(quote(b))}"><h2>{e(b)}</h2><span>{sum(p["brand"]==b for p in products)} {"product" if sum(p["brand"]==b for p in products)==1 else "products"} <b>↗</b></span></a>' for b in brands)+'</section>'
 page('brands.html','Accessory Brands','Browse brands in the Ashes accessory storefront demo.',brandbody,'brands')
 for name,title,root in [('cart.html','Your cart','cart'),('checkout.html','Checkout','checkout')]:
  page(name,title,'Try the Ashes storefront demo, with no real orders or payments.',f'<section class="store-page-heading mint"><a class="text-link" href="explore.html">← Keep shopping</a><h1>{title}</h1><p>Demo inventory. No payment will be taken and no order will be sent.</p></section><section class="cart-shell"><div data-{root}-root></div><noscript>Enable JavaScript to use the shopping cart and demo checkout.</noscript></section>','products')
 rows=''.join(f'<tr><td><a href="product-{p["id"]}.html">{e(p["name"])}</a></td><td>{e(p["source"]["retailer"])}</td><td>{price(p)}</td><td><a href="{e(p["source"]["url"])}" target="_blank" rel="noopener">Listing ↗</a></td></tr>' for p in products)
 about=f'''<section class="retail-hero"><div><span class="retail-kicker">STOREFRONT PREVIEW</span><h1>A store you can try.</h1><p>Real accessory examples. A working shopping flow. No real transactions.</p></div></section><section class="retail-about"><h2>Where the products come from</h2><p>The {len(products)} products in this preview are sourced from public listings by nearby smoke shops. Product names, photos and reference prices are used to demonstrate a realistic retail experience. They do not establish Ashes’s current inventory, prices, supplier relationships or availability.</p><h2>What works in the preview</h2><p>Search, category and brand filters, price sorting, product pages, a saved cart, quantity changes, pickup and shipping choices, example tax and shipping calculations, and a local demo order confirmation. The checkout does not collect payment details, send an order, reserve stock or contact Ashes. Contact and address fields are not stored by the demo. Cart selections remain in this browser.</p><h2>Before taking real orders</h2><p>Ashes would supply its approved product records, stock, prices, policies and fulfillment settings, and connect its own payment and order systems. Competitor photos would need permission for continued use or replacement with Ashes-owned or licensed images before a production launch. The demo’s $5 shipping and 8.25% tax are examples for showing calculations, not quotes or tax determinations.</p><details><summary>View product references · checked November 12, 2026</summary><div class="retail-source-table"><table><thead><tr><th>Product</th><th>Retailer</th><th>Reference price</th><th>Source</th></tr></thead><tbody>{rows}</tbody></table></div></details></section>'''
 page('catalog-about.html','About the Storefront Preview','Product sources and the working boundaries of the Ashes demo.',about,'products')
